E=ROOT/'evidence'
def meta(name): return json.loads((E/(name+'.json')).read_text())
def source(url,claim,path): return dict(url=url,claim=claim,evidence_path=path)
def size(value,unit,date,url,path,quality='official',note=''): return dict(value=value,unit=unit,date=date,source_url=url,evidence_path=path,quality=quality,note=note)
def robot(name,target,initial=False):
 if initial:
  m=json.loads((E/name/'robots.json').read_text());decision='no_published_rules' if m['status']==404 else 'unresolved';p='evidence/'+name+'/robots.json';note='HTTP 404: no published robots rule; not an affirmative reuse licence.'
 else:
  m=meta(name);d=robots_decision(E/(name+'.json'),target);decision=d['decision'];p=m['metadata_path'];note=d['note']
 return dict(url=m['url'],status=m['status'],checked_at_utc=m['checked_at_utc'],evidence_path=p,decision=decision,note=note)
def query(name,text,count,match='exact_title',note=''):
 m=meta(name);return dict(text=text,method=m['method'],url=m['url'],payload=m['payload'],checked_at_utc=m['checked_at_utc'],http_status=m['status'],effective_url=m['effective_url'],result_count=count,count_note=note,match_type=match,evidence_path=m['evidence_path'],metadata_path=m['metadata_path'])
def book(title,author,id,url,hold,ev,isbn=None):return dict(title=title,author=author,record_id=id,record_url=url,isbn=isbn,holdings=hold,evidence_path=ev)
