 return dict(id='mexico-'+id,name=name,recommendation=recommendation,scope=scope,size=siz,platform=dict(family=family,name=family,proof=proof,evidence_path=q['evidence_path']),query=q,books=b,robots=rob,reader_access=access,integration=dict(existing_adapter='candidate reuse' if family=='Koha' else 'new family' if family=='Aleph' else 'custom',needs=needs,blockers=list(blockers or []),live_app_tested=False))
